parameters.jsCode:
const items = $input.all();
let hasSuccess = false;

for (const item of items) {
  // Check email success (has accepted array)
  if (item.json.accepted && item.json.accepted.length > 0 && 
      (!item.json.rejected || item.json.rejected.length === 0)) {
    hasSuccess = true;
    break;
  }

  // Check SMS success (has data field with OK status)
  if (item.json.data) {
    try {
      const smsData = JSON.parse(item.json.data);
      if (smsData.id === 'OK' && 
          smsData.data?.recipients?.accepted?.length > 0) {
        hasSuccess = true;
        break;
      }
    } catch (e) {
      // SMS data parsing failed, continue checking other items
    }
  }
}

// Return success if ANY communication method succeeded
return hasSuccess ? [{ success: true }] : [{ success: false }];

